import numpy as np
from scipy.optimize import minimize

def capped_simplex_projection(v, m):
    v = np.asarray(v, dtype=np.float64)
    n = len(v)
    if n == 0:
        return v
    lo = np.min(v) - 1.0
    hi = np.max(v)
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        s = np.sum(np.clip(v - mid, 0.0, 1.0))
        if s > m:
            lo = mid
        else:
            hi = mid
    h = np.clip(v - 0.5 * (lo + hi), 0.0, 1.0)
    r = m - np.sum(h)
    if abs(r) > 5e-13:
        if r > 0:
            idx = np.argsort(1.0 - h)[::-1]
            for i in idx:
                if r <= 0:
                    break
                add = min(r, 1.0 - h[i])
                h[i] += add
                r -= add
        else:
            idx = np.argsort(h)[::-1]
            for i in idx:
                if r >= 0:
                    break
                sub = min(-r, h[i])
                h[i] -= sub
                r += sub
    if abs(np.sum(h) - m) > 1e-10:
        return np.full(n, 0.5, dtype=np.float64)
    return h

def exact_score(h):
    h = np.asarray(h, dtype=np.float64)
    n = len(h)
    if n == 0 or not np.all(np.isfinite(h)):
        return float('inf')
    dx = 2.0 / n
    return float(np.max(np.correlate(h, 1.0 - h, mode='full') * dx))

def compute_lags(h, dx):
    n = len(h)
    n_lags = 2 * n - 1
    Q = np.zeros(n_lags)
    G = np.zeros((n_lags, n))
    for d in range(-(n - 1), n):
        row = d + (n - 1)
        lo = max(0, -d)
        hi = min(n, n - d)
        left = slice(lo, hi)
        right = slice(lo + d, hi + d)
        Q[row] = dx * np.dot(h[left], 1.0 - h[right])
        G[row, left] += dx * (1.0 - h[right])
        G[row, right] -= dx * h[left]
    return Q, G

def obj_fun(z, n):
    return z[n]

def obj_jac(z, n):
    g = np.zeros(n + 1)
    g[n] = 1.0
    return g

def con_eq_fun(z, n):
    return np.sum(z[:n]) - n / 2.0

def con_eq_jac(z, n):
    g = np.zeros(n + 1)
    g[:n] = 1.0
    return g

def con_ineq_fun(z, n, dx):
    h = z[:n]
    Q, _ = compute_lags(h, dx)
    return z[n] - Q

def con_ineq_jac(z, n, dx):
    h = z[:n]
    _, G = compute_lags(h, dx)
    J = np.zeros((2 * n - 1, n + 1))
    J[:, :n] = -G
    J[:, n] = 1.0
    return J

def generate_starts(base, n, rng):
    starts = [base.copy()]
    for sigma in [0.03, 0.08, 0.20]:
        v = base + sigma * rng.standard_normal(n)
        starts.append(capped_simplex_projection(v, n / 2.0))
    v = rng.standard_normal(n) * 0.6
    starts.append(capped_simplex_projection(v, n / 2.0))
    i = np.arange(n)
    for k in [1, 2, 3]:
        phase = rng.uniform(0, 2 * np.pi)
        v = 0.5 + 0.35 * np.cos(2 * np.pi * k * i / n + phase)
        starts.append(capped_simplex_projection(v, n / 2.0))
    return starts

def try_solve(z0, n, dx):
    bounds = [(0.0, 1.0)] * n + [(0.0, 1.01)]
    cons = [
        {'type': 'eq', 'fun': con_eq_fun, 'jac': con_eq_jac, 'args': (n,)},
        {'type': 'ineq', 'fun': con_ineq_fun, 'jac': con_ineq_jac, 'args': (n, dx)}
    ]
    maxiter = min(600, 300 + 2 * n)
    try:
        res = minimize(obj_fun, z0, method='SLSQP', jac=obj_jac,
                       bounds=bounds, constraints=cons, args=(n,),
                       options={'ftol': 1e-10, 'maxiter': maxiter, 'disp': False})
        if res.x.shape[0] == n + 1 and np.all(np.isfinite(res.x)):
            return capped_simplex_projection(res.x[:n], n / 2.0)
    except Exception:
        pass
    return None

def run(seed=42, **kwargs):
    rng = np.random.default_rng(seed)
    parent = globals().get('initial_h_values', None)
    base_n = None
    h_base = None
    if parent is not None:
        try:
            p = np.asarray(parent, dtype=np.float64).ravel()
            if 2 <= len(p) <= 128:
                base_n = len(p)
                if np.all(np.isfinite(p)):
                    h_base = capped_simplex_projection(p, base_n / 2.0)
        except Exception:
            pass
    if base_n is None:
        base_n = 45
        h_base = np.full(base_n, 0.5)
    if h_base is None:
        h_base = np.full(base_n, 0.5)
    h_base = np.clip(h_base, 0.0, 1.0)

    best_h = h_base.copy()
    best_score = exact_score(h_base)
    dx = 2.0 / base_n

    starts = generate_starts(h_base, base_n, rng)
    for start in starts:
        s_score = exact_score(start)
        if s_score < best_score - 1e-12:
            best_score = s_score
            best_h = start.copy()
        t0 = min(1.01, s_score + 1e-7)
        z0 = np.concatenate([start, [t0]])
        h_sol = try_solve(z0, base_n, dx)
        if h_sol is not None:
            sol_score = exact_score(h_sol)
            if sol_score < best_score - 1e-12:
                best_score = sol_score
                best_h = h_sol.copy()

    t0 = min(1.01, best_score + 1e-7)
    z0 = np.concatenate([best_h, [t0]])
    h_sol = try_solve(z0, base_n, dx)
    if h_sol is not None:
        sol_score = exact_score(h_sol)
        if sol_score < best_score - 1e-12:
            best_score = sol_score
            best_h = h_sol.copy()

    if base_n <= 64:
        fine_n = 2 * base_n
        fine_dx = 2.0 / fine_n
        fine_rng = np.random.default_rng(seed + 1)
        h_fine = capped_simplex_projection(np.repeat(best_h, 2), fine_n / 2.0)
        fine_best_h = h_fine.copy()
        fine_best_score = exact_score(h_fine)
        fine_starts = generate_starts(h_fine, fine_n, fine_rng)
        p_trans = capped_simplex_projection(np.repeat(h_base, 2), fine_n / 2.0)
        if not np.allclose(p_trans, fine_starts[0]):
            fine_starts.append(p_trans)
        for start in fine_starts:
            s_score = exact_score(start)
            if s_score < fine_best_score - 1e-12:
                fine_best_score = s_score
                fine_best_h = start.copy()
            t0 = min(1.01, s_score + 1e-7)
            z0 = np.concatenate([start, [t0]])
            h_sol = try_solve(z0, fine_n, fine_dx)
            if h_sol is not None:
                sol_score = exact_score(h_sol)
                if sol_score < fine_best_score - 1e-12:
                    fine_best_score = sol_score
                    fine_best_h = h_sol.copy()
        t0 = min(1.01, fine_best_score + 1e-7)
        z0 = np.concatenate([fine_best_h, [t0]])
        h_sol = try_solve(z0, fine_n, fine_dx)
        if h_sol is not None:
            sol_score = exact_score(h_sol)
            if sol_score < fine_best_score - 1e-12:
                fine_best_score = sol_score
                fine_best_h = h_sol.copy()
        if fine_best_score < best_score - 1e-12:
            best_score = fine_best_score
            best_h = fine_best_h.copy()

    best_h = np.asarray(best_h, dtype=np.float64)
    n_pts = len(best_h)
    if not np.all(np.isfinite(best_h)):
        best_h = np.full(base_n, 0.5)
        n_pts = base_n
    best_h = capped_simplex_projection(best_h, n_pts / 2.0)
    best_score = exact_score(best_h)
    return (best_h, best_score, int(n_pts))
